import React, { useState } from 'react';
import './MyPage.css'; // MyPage 전용 스타일
import UserInfoTab from './components/UserInfoTab';
import TravelDrawerTab from './components/TravelDrawerTab';
import JourneyShareTab from './components/JourneyShareTab';
import InquiryBoardTab from './components/InquiryBoardTab';

const MyPage = () => {
  const [activeTab, setActiveTab] = useState('userInfo'); // 기본 탭: 회원 정보

  // 가상의 사용자 정보 (백엔드에서 받아올 데이터)
  const userInfo = {
    name: '도몬',
    email: 'domon@example.com',
    avatar: 'https://via.placeholder.com/150/007bff/FFFFFF?text=DOMON',
    membershipLevel: '일반 회원',
    registeredDate: '2024-01-01',
    // ...등등 실제 필요한 회원 정보
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'userInfo':
        return <UserInfoTab userInfo={userInfo} />;
      case 'travelDrawer':
        return <TravelDrawerTab />;
      case 'journeyShare':
        return <JourneyShareTab />;
      case 'inquiryBoard':
        return <InquiryBoardTab />;
      default:
        return <UserInfoTab userInfo={userInfo} />;
    }
  };

  return (
    <div className="my-page-container">
      <h1 className="my-page-title">나의 여정 🚶‍♀️</h1>
      <div className="my-page-tabs">
        <button
          className={`tab-button ${activeTab === 'userInfo' ? 'active' : ''}`}
          onClick={() => setActiveTab('userInfo')}
        >
          회원 정보
        </button>
        <button
          className={`tab-button ${activeTab === 'travelDrawer' ? 'active' : ''}`}
          onClick={() => setActiveTab('travelDrawer')}
        >
          여행 서랍
        </button>
        <button
          className={`tab-button ${activeTab === 'journeyShare' ? 'active' : ''}`}
          onClick={() => setActiveTab('journeyShare')}
        >
          여정 나누기
        </button>
        <button
          className={`tab-button ${activeTab === 'inquiryBoard' ? 'active' : ''}`}
          onClick={() => setActiveTab('inquiryBoard')}
        >
          문의 게시판
        </button>
      </div>
      <div className="my-page-content">
        {renderTabContent()}
      </div>
    </div>
  );
};

export default MyPage;
